type Order = {
    customerId: string;
    amountCents: number;
    status: 'paid' | 'refunded' | 'pending';
};
export function summarizeOrderBalances(orders: Order[]): {
    customerId: string;
    balanceCents: number;
}[] {
    const balances = new Map<string, number>();
    for (const row of orders) {
        if (!row.customerId.trim() || !Number.isSafeInteger(row.amountCents) || row.amountCents < 0 || !['paid', 'refunded', 'pending'].includes(row.status)) {
            throw new Error('Invalid order');
        }
        const change = row.status === 'paid' ? row.amountCents : row.status === 'refunded' ? -row.amountCents : 0;
        balances.set(row.customerId, (balances.get(row.customerId) ?? 0) + change);
    }
    return [...balances].sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0).map(([customerId, balanceCents]) => ({ customerId, balanceCents }));
}
